+        q_scale->is_cuda() &&
+            q_scale->get_device_index() == qkv.get_device_index() &&
+            q_scale->scalar_type() == torch::headeronly::ScalarType::Float &&
+            q_scale->numel() == 1,
+        "q_scale must be a single fp32 value on the qkv device");
+  }
