+                    "cos_sin_cache shape must be [max_pos, rotary_dim]");
+    STD_TORCH_CHECK(
+        cos_sin_cache->scalar_type() == torch::headeronly::ScalarType::Float ||
+            cos_sin_cache->scalar_type() == qkv.scalar_type(),
+        "cos_sin_cache must be float32 or match the qkv dtype");
