+                    "kv_cache content dim must be 2*head_dim");
+    STD_TORCH_CHECK(kv_cache->size(1) == nkv,
+                    "kv_cache head dim must equal num_kv_heads");
+    STD_TORCH_CHECK(kv_cache->size(2) == block_size,
+                    "kv_cache token dim must equal block_size");
