+      qkv.scalar_type(), "fused_muse_spark_qknorm_rope_kv_insert", [&] {
+        using st = scalar_t;
+        DISPATCH_BY_KV_CACHE_DTYPE(qkv.scalar_type(), kv_cache_dtype,
